import json
import sys

data = json.load(sys.stdin)
print(f"Total records: {len(data)}")
print()

# Group by kind
by_kind = {}
for record in data:
    kind = record.get("kind", "unknown")
    if kind not in by_kind:
        by_kind[kind] = []
    by_kind[kind].append(record)

print("By kind:")
for kind, records in sorted(by_kind.items()):
    print(f"  {kind}: {len(records)}")
print()

# Group by error type
by_error = {}
for record in data:
    error = record.get("error", "")[:80]
    if error not in by_error:
        by_error[error] = []
    by_error[error].append(record)

print("By error type:")
for error, records in sorted(by_error.items(), key=lambda x: -len(x[1]))[:10]:
    print(f"  {len(records):2d}x {error}...")
print()

# Extract packages with failures
packages = {}
for record in data:
    pkg = record.get("package")
    if pkg:
        if pkg not in packages:
            packages[pkg] = []
        packages[pkg].append(record["id"])

print("Packages with failures:")
for pkg in sorted(packages.keys()):
    print(f"  {pkg}: {len(packages[pkg])} record(s)")
EOF

